create temporary view order_raw_${grass_region_without_quote} as
select is_ads
    ,user_id
    ,model_id
    ,traffic_vsku_item_id
    ,order_cnt
    ,gmv
    ,case when reporting_business_line = 'Search' and reporting_module = 'Global Search' then 'Search'
        when reporting_business_line = 'Homepage' and reporting_module = 'Daily Discover' then 'Daily Discover'
        when reporting_business_line = 'Rcmd' and reporting_object = 'you may also like' then 'You May Also Like'
        when reporting_business_line = 'Rcmd' and reporting_module = 'User Scenario' and reporting_object = 'post purchase' then 'Post Purchase'
    else 'other' end as scene
    ,case when source1_reporting_business_line = 'Search' and source1_reporting_module = 'Global Search' then 'Search'
        when source1_reporting_business_line = 'Homepage' and source1_reporting_module = 'Daily Discover' then 'Daily Discover'
        when source1_reporting_business_line = 'Rcmd' and source1_reporting_object = 'you may also like' then 'You May Also Like'
        when source1_reporting_business_line = 'Rcmd' and source1_reporting_module = 'User Scenario' and source1_reporting_object = 'post purchase' then 'Post Purchase'
    else 'other' end as source1_scene
    ,case when source2_reporting_business_line = 'Search' and source2_reporting_module = 'Global Search' then 'Search'
        when source2_reporting_business_line = 'Homepage' and source2_reporting_module = 'Daily Discover' then 'Daily Discover'
        when source2_reporting_business_line = 'Rcmd' and source2_reporting_object = 'you may also like' then 'You May Also Like'
        when source2_reporting_business_line = 'Rcmd' and source2_reporting_module = 'User Scenario' and source2_reporting_object = 'post purchase' then 'Post Purchase'
    else 'other' end as source2_scene
    ,feature_detail
    ,source1_feature_detail
    ,source2_feature_detail
from srdi_mart.dwm_sr_data_warehouse_tc_ab_all_cards
where
    grass_region = ${grass_region}
    and local_date = ${local_date}
    and operation = 'order'
    and is_item_card = 'true'
    and user_id > 0
;

