create temporary view imp_base_${grass_region_without_quote} as
select
    user_id
    ,case
        when array_contains(scenario_tags, 'dpm module Global Search business line Search') then 'Search'
        when array_contains(scenario_tags, 'dpm module Daily Discover business line Homepage') then 'Daily Discover'
        when array_contains(scenario_tags, 'dpm reporting object post purchase module User Scenario business line Rcmd') then 'Post Purchase'
        when exists(scenario_tags, x -> x like 'dpm reporting object you may also like % business line Rcmd') then 'You May Also Like'
    end as scene
    ,if(is_ads is true, 'true', 'false') as is_ads
    ,case when if(split(feature_detail,'-')[2] IS NOT null, split(feature_detail,'-')[2], split(feature_detail,'-')[1])='video' then 1
        else 0 end as is_video_card
    ,if(t2.item_id is not null, 1, 0) as is_cspu
    ,if(t3.vitem_id is not null, 1, 0) as is_vitem
    ,sum(omni_scenario_imp_cnt) as omni_scenario_imp_cnt
    ,sum(omni_scenario_click_cnt) as omni_scenario_click_cnt
from
    srdi_mart.dwm_sr_data_warehouse_platform_user_item as t1
left join
    (select distinct item_id from cspu_item_model_list_${grass_region_without_quote}) as t2
on
    t1.item_id = t2.item_id
left join
    (select distinct vitem_id from vitem_cspu_list_${grass_region_without_quote}) as t3
on
    t1.item_id = t3.vitem_id
where
    grass_region = ${grass_region}
    and local_date = ${local_date}
    and operation in('omni_impression','omni_click')
    and user_id > 0
group by 1,2,3,4,5,6;
--sql_divide_splitter--

