     ,sum(omni_scenario_imp_cnt) as omni_scenario_imp_cnt
     ,sum(omni_scenario_click_cnt) as omni_scenario_click_cnt
    from imp_base_${grass_region_without_quote}
where scene in ('Daily Discover', 'You May Also Like','Post Purchase')
group by 1,2,3,4,5,6
;

--sql_divide_splitter--
create temporary view scene_level_imp_${grass_region_without_quote} as
select
    t1.scene
    ,exp_group_id
    ,coalesce(is_ads, '__ALL__') as is_ads
    ,coalesce(is_video_card, '__ALL__') as is_video_card
    ,sum(if(is_cspu = 1, omni_scenario_imp_cnt, 0)) as cspu_omni_scenario_imp_cnt
    ,sum(if(is_vitem = 1, omni_scenario_imp_cnt, 0)) as vitem_omni_scenario_imp_cnt
    ,sum(omni_scenario_imp_cnt) as scene_omni_scenario_imp_cnt
    ,sum(if(is_vitem = 1, omni_scenario_click_cnt, 0)) as vitem_omni_scenario_click_cnt
    ,sum(if(is_cspu = 1, omni_scenario_click_cnt, 0)) as cspu_omni_scenario_click_cnt
from (
    SELECT *
    FROM imp_base_${grass_region_without_quote}
