create temporary view scene_level_imp_and_order_${grass_region_without_quote} as
select is_ads
     ,scene
     ,exp_group_id
     ,is_video_card
     ,sum(cspu_omni_scenario_imp_cnt) as cspu_omni_scenario_imp_cnt
