--sql_divide_splitter--
insert overwrite table ${schema}.dws_sr_data_warehouse_tc_vsku_scene_exp_1d
partition (grass_region = ${grass_region}, local_date = ${local_date})
select
    t1.is_ads
    ,t1.scene
    ,t1.exp_group_id

    ,coalesce(vitem_omni_scenario_imp_cnt, 0) as vitem_omni_scenario_imp_cnt
    ,coalesce(vitem_order_cnt, 0) as vitem_order_cnt
    ,coalesce(cspu_omni_scenario_imp_cnt, 0) as cspu_omni_scenario_imp_cnt
    ,coalesce(cspu_order_cnt, 0) as cspu_order_cnt
    ,coalesce(scene_omni_scenario_imp_cnt, 0) as scene_omni_scenario_imp_cnt
    ,coalesce(scene_order_cnt, 0) as scene_order_cnt
    ,if(cspu_order_cnt > 0, vitem_order_cnt / cspu_order_cnt, 0) as vitem_cspu_order_ratio
    ,if(cspu_omni_scenario_imp_cnt > 0, vitem_omni_scenario_imp_cnt / cspu_omni_scenario_imp_cnt, 0) as vitem_cspu_imp_ratio
    ,if(scene_order_cnt > 0, vitem_order_cnt / scene_order_cnt, 0) as vitem_scene_order_ratio
    ,if(scene_omni_scenario_imp_cnt > 0, vitem_omni_scenario_imp_cnt / scene_omni_scenario_imp_cnt, 0) as vitem_scene_imp_ratio
    ,coalesce(vitem_omni_scenario_click_cnt,0) as vitem_omni_scenario_click_cnt
    ,coalesce(vitem_gmv,0) as vitem_gmv
    ,coalesce(cspu_omni_scenario_click_cnt,0) as cspu_omni_scenario_click_cnt
    ,coalesce(platform_omni_scenario_imp_cnt,0) as platform_omni_scenario_imp_cnt
    ,platform_order_cnt
    ,t1.is_video_card
from scene_level_imp_and_order_${grass_region_without_quote} t1
left join platform_level_order_${grass_region_without_quote} as t3
on t1.exp_group_id = t3.exp_group_id
and t1.is_ads = t3.is_ads
and t1.is_video_card = t3.is_video_card
left join platform_level_imp_${grass_region_without_quote} as t4
on t1.exp_group_id = t4.exp_group_id
and t1.is_ads = t4.is_ads
and t1.is_video_card = t4.is_video_card
;
